using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalAcceptanceTests
{
    [Theory]
    [InlineData(LoyaltyTier.Green, 4_999, 4_750)]    // 5%, floor(249.95)=249
    [InlineData(LoyaltyTier.Green, 5_000, 4_700)]    // threshold -> 6%
    [InlineData(LoyaltyTier.Gold, 4_999, 4_650)]     // 7%, floor(349.93)=349
    [InlineData(LoyaltyTier.Platinum, 4_999, 4_550)] // 9%, floor(449.91)=449
    [InlineData(LoyaltyTier.Gold, 5_000, 4_600)]     // 8%
    [InlineData(LoyaltyTier.Platinum, 5_000, 4_500)]   // 10%
    [InlineData(LoyaltyTier.Green, 10_000, 9_400)]
    [InlineData(LoyaltyTier.Green, 19_999, 18_800)]  // 6%, floor(1199.94)=1199
    [InlineData(LoyaltyTier.Green, 20_000, 18_400)]  // 8%
    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]   // 10%
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)] // capped 10%
    [InlineData(LoyaltyTier.Platinum, 19_999, 18_000)] // 10%, floor(1999.9)=1999
    [InlineData(LoyaltyTier.Green, 99, 94)]          // floor(4.95)=4
    [InlineData(LoyaltyTier.Green, 0, 0)]
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier tier, int subtotalCents, int expectedPayableCents)
    {
        Assert.Equal(expectedPayableCents, new CalculatePayableTotal().For(subtotalCents, tier));
    }
}
E
